-- Start Simple redesign: lesson descriptions, level preview sentences, and
-- the rewritten normal-mode content library (12 lessons x 9 sentences,
-- replacing the previous 8 lessons x 12 sentences).
--
-- Generated from the same TypeScript source the app reads locally
-- (src/data/lessons/normal.ts, src/data/units.ts) by a one-off script
-- mirroring scripts/generate-content-seed.ts's approach: one authored
-- copy of the content, not two hand-kept-in-sync copies.
--
-- Idempotent and additive-only for everything except the 12 known
-- normal-mode lesson ids listed below: upserts key on stable ids (levels:
-- mode+index; lessons/sentences: their existing slug-style id), and the
-- stale-sentence cleanup near the end only ever deletes rows beyond the
-- new 9-sentence count for those same 12 ids. Stories, Conversation,
-- profiles, progress, XP, streaks, and subscriptions are never referenced
-- or touched anywhere in this file.
--
-- Wrapped in an explicit transaction: if any statement fails, everything
-- in this file rolls back together and the database is left exactly as it
-- was before this ran. Run the verification queries at the bottom of this
-- file separately, after this migration commits, to confirm the result.
begin;

alter table lessons
  add column if not exists description text,
  add column if not exists description_ar text;

alter table levels
  add column if not exists preview_sentences jsonb not null default '[]'::jsonb;

-- Levels: renamed to Beginner/Intermediate/Advanced, with Start Simple previews

-- Lessons: full replacement of the normal-mode library, by id.
--
-- The lessons table has a unique constraint on (mode, order_index). The
-- live database already has the pre-redesign rows normal-1..normal-8 at
-- order_index 1-8, and this migration both reassigns order_index for those
-- and introduces normal-9..normal-12 at order_index values an old row may
-- still be sitting on (for example normal-9 below targets order_index 8,
-- which the old normal-8 row occupies until its own upsert further down).
-- Upserting one lesson at a time in target order collides with a
-- not-yet-moved sibling row and raises error 23505.
--
-- Fix: move exactly the 12 lesson ids this migration owns out of the
-- order_index range it is about to assign (1 through 12), before touching
-- any of them, matched by id, not by an order_index range and not by a
-- bare mode filter. This is deliberately narrower than either option: it
-- can never move a lesson this migration does not know about (for example
-- one created later through the admin CMS), and it correctly moves all 12
-- target ids regardless of whatever order_index each currently holds,
-- including normal-9 through normal-12 if an earlier partial attempt
-- already created them. Once every one of these 12 rows is parked at 1000
-- or above, none of the order_index values 1 through 12 are held by
-- anyone, so the upserts below can assign them in any order with zero
-- collision risk, including on a rerun after a failed attempt, in
-- whatever state that attempt left things in, committed or not.
update lessons
set order_index = order_index + 1000
where mode = 'normal'
  and id in (
    'normal-1', 'normal-2', 'normal-3', 'normal-4',
    'normal-5', 'normal-6', 'normal-7', 'normal-8',
    'normal-9', 'normal-10', 'normal-11', 'normal-12'
  );


-- Sentences (including word_translations, which the original seed migration predates)

-- Cleanup: these lessons previously had 12 sentences (order_index 0-11); remove the now-stale trailing three.
delete from sentences where lesson_id in ('normal-1', 'normal-2', 'normal-3', 'normal-4', 'normal-5', 'normal-6', 'normal-7', 'normal-8') and order_index >= 9;

commit;

-- Verification (run separately, after the transaction above has committed):
-- plain read-only SELECTs, no procedural code, safe to run any number of
-- times. Expected results are noted next to each one.

-- Expect exactly 12 rows.
select id, order_index, title, is_free, status
from lessons
where mode = 'normal'
  and id in (
    'normal-1', 'normal-2', 'normal-3', 'normal-4',
    'normal-5', 'normal-6', 'normal-7', 'normal-8',
    'normal-9', 'normal-10', 'normal-11', 'normal-12'
  )
order by order_index;

-- Expect exactly 12 rows, each with sentence_count = 9 (total 108).
select lesson_id, count(*) as sentence_count
from sentences
where lesson_id in (
    'normal-1', 'normal-2', 'normal-3', 'normal-4',
    'normal-5', 'normal-6', 'normal-7', 'normal-8',
    'normal-9', 'normal-10', 'normal-11', 'normal-12'
  )
group by lesson_id
order by lesson_id;
