insert into levels (mode, index, title, title_ar, preview_sentences) values ('normal', 1, 'Beginner — A1', 'مبتدئ — A1', '[{"en":"My phone died right before my bus arrived.","ar":"توقف هاتفي عن العمل قبل وصول الحافلة مباشرة."},{"en":"I ordered coffee, but they gave me tea.","ar":"طلبت قهوة، لكنهم أعطوني شايًا."},{"en":"She found ten dollars on the street.","ar":"وجدت عشرة دولارات في الشارع."},{"en":"We waited an hour for a table.","ar":"انتظرنا ساعة للحصول على طاولة."},{"en":"He forgot his password again.","ar":"نسي كلمة المرور مرة أخرى."}]'::jsonb) on conflict (mode, index) do update set title = excluded.title, title_ar = excluded.title_ar, preview_sentences = excluded.preview_sentences;
insert into levels (mode, index, title, title_ar, preview_sentences) values ('normal', 2, 'Intermediate — A2-B1', 'متوسط — A2-B1', '[{"en":"I almost missed my flight because of the traffic.","ar":"كدت أفوت رحلتي بسبب الازدحام المروري."},{"en":"She''s been learning English for six months now.","ar":"إنها تتعلم الإنجليزية منذ ستة أشهر الآن."},{"en":"We couldn''t agree on where to go for dinner.","ar":"لم نستطع الاتفاق على أين نذهب لتناول العشاء."},{"en":"He quit his job to travel for a year.","ar":"استقال من وظيفته ليسافر لمدة عام."},{"en":"I''ve started saving money instead of spending it all.","ar":"بدأت أدخر المال بدلاً من إنفاقه كله."}]'::jsonb) on conflict (mode, index) do update set title = excluded.title, title_ar = excluded.title_ar, preview_sentences = excluded.preview_sentences;
insert into levels (mode, index, title, title_ar, preview_sentences) values ('normal', 3, 'Advanced — B2+', 'متقدم — B2+', '[{"en":"I used to dread public speaking, but I''ve slowly gotten the hang of it.","ar":"كنت أخشى التحدث أمام الجمهور، لكنني أتقنت الأمر تدريجيًا."},{"en":"Looking back, quitting that job was the best decision I ever made.","ar":"بالنظر إلى الماضي، كانت الاستقالة من تلك الوظيفة أفضل قرار اتخذته في حياتي."},{"en":"She has a knack for turning awkward situations into something funny.","ar":"لديها موهبة في تحويل المواقف المحرجة إلى شيء مضحك."},{"en":"The plan sounded great on paper, but it fell apart within a week.","ar":"بدت الخطة رائعة على الورق، لكنها انهارت خلال أسبوع."},{"en":"He''s not lazy, exactly — he just prioritizes things differently than most people.","ar":"إنه ليس كسولًا بالضبط، بل يرتب أولوياته بشكل مختلف عن معظم الناس."}]'::jsonb) on conflict (mode, index) do update set title = excluded.title, title_ar = excluded.title_ar, preview_sentences = excluded.preview_sentences;
