insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-8-s5', 'normal-8', 4, 'That evening, I sat down and rewrote my entire resume', 'في تلك الأمسية، جلست وأعدت كتابة سيرتي الذاتية بالكامل.', null, '[{"en":"That","ar":"تلك"},{"en":"evening,","ar":"الأمسية،"},{"en":"I","ar":"أنا"},{"en":"sat","ar":"جلست"},{"en":"down","ar":"أسفل"},{"en":"and","ar":"و"},{"en":"rewrote","ar":"أعدت كتابة"},{"en":"my","ar":"لي"},{"en":"entire","ar":"بالكامل"},{"en":"resume","ar":"سيرتي الذاتية"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-8-s6', 'normal-8', 5, 'I stopped padding it with buzzwords and focused on what I''d actually built', 'توقفت عن حشوها بكلمات رنانة وركزت على ما بنيته فعلاً.', null, '[{"en":"I","ar":"أنا"},{"en":"stopped","ar":"توقفت"},{"en":"padding","ar":"حشو"},{"en":"it","ar":"ها"},{"en":"with","ar":"بـ"},{"en":"buzzwords","ar":"كلمات رنانة"},{"en":"and","ar":"و"},{"en":"focused","ar":"ركزت"},{"en":"on","ar":"على"},{"en":"what","ar":"ما"},{"en":"I''d","ar":"كنت"},{"en":"actually","ar":"فعلاً"},{"en":"built","ar":"بنيته"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-8-s7', 'normal-8', 6, 'When the interview finally happened, I felt oddly calm', 'عندما جرت المقابلة أخيراً، شعرت بهدوء غريب.', null, '[{"en":"When","ar":"عندما"},{"en":"the","ar":"الـ"},{"en":"interview","ar":"المقابلة"},{"en":"finally","ar":"أخيراً"},{"en":"happened,","ar":"جرت،"},{"en":"I","ar":"أنا"},{"en":"felt","ar":"شعرت"},{"en":"oddly","ar":"بشكل غريب"},{"en":"calm","ar":"بهدوء"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-8-s8', 'normal-8', 7, 'The recruiter said my answers stood out from everyone else''s', 'قال المسؤول إن إجاباتي تميّزت عن إجابات الجميع.', null, '[{"en":"The","ar":"الـ"},{"en":"recruiter","ar":"المسؤول"},{"en":"said","ar":"قال"},{"en":"my","ar":"لي"},{"en":"answers","ar":"إجاباتي"},{"en":"stood","ar":"تميّزت"},{"en":"out","ar":"بشدة"},{"en":"from","ar":"عن"},{"en":"everyone","ar":"الجميع"},{"en":"else''s","ar":"الآخرين"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-8-s9', 'normal-8', 8, 'Looking back, that last-minute delay turned out to be a gift', 'بالنظر إلى الوراء، تبيّن أن ذلك التأجيل المفاجئ كان نعمة.', null, '[{"en":"Looking","ar":"بالنظر"},{"en":"back,","ar":"إلى الوراء،"},{"en":"that","ar":"ذلك"},{"en":"last-minute","ar":"المفاجئ"},{"en":"delay","ar":"التأجيل"},{"en":"turned","ar":"تبيّن"},{"en":"out","ar":"أنه"},{"en":"to","ar":"أن"},{"en":"be","ar":"يكون"},{"en":"a","ar":"واحدة"},{"en":"gift","ar":"نعمة"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-10-s1', 'normal-10', 0, 'We''d been close friends since university, practically inseparable', 'كنا أصدقاء مقربين منذ الجامعة، شبه متلازمين.', null, '[{"en":"We''d","ar":"كنا"},{"en":"been","ar":"قد"},{"en":"close","ar":"مقربين"},{"en":"friends","ar":"أصدقاء"},{"en":"since","ar":"منذ"},{"en":"university,","ar":"الجامعة،"},{"en":"practically","ar":"شبه"},{"en":"inseparable","ar":"متلازمين"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-10-s2', 'normal-10', 1, 'Somewhere along the way, we just stopped making time for each other', 'في مرحلة ما، توقفنا ببساطة عن تخصيص وقت لبعضنا.', null, '[{"en":"Somewhere","ar":"في مكان ما"},{"en":"along","ar":"على"},{"en":"the","ar":"الـ"},{"en":"way,","ar":"الطريق،"},{"en":"we","ar":"نحن"},{"en":"just","ar":"ببساطة"},{"en":"stopped","ar":"توقفنا"},{"en":"making","ar":"تخصيص"},{"en":"time","ar":"وقت"},{"en":"for","ar":"لـ"},{"en":"each","ar":"بعضنا"},{"en":"other","ar":"البعض"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-10-s3', 'normal-10', 2, 'A careless comment at a dinner party made things worse', 'جعل تعليق طائش في حفل عشاء الأمور أسوأ.', null, '[{"en":"A","ar":"واحد"},{"en":"careless","ar":"طائش"},{"en":"comment","ar":"تعليق"},{"en":"at","ar":"في"},{"en":"a","ar":"واحد"},{"en":"dinner","ar":"عشاء"},{"en":"party","ar":"حفل"},{"en":"made","ar":"جعل"},{"en":"things","ar":"الأمور"},{"en":"worse","ar":"أسوأ"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-10-s4', 'normal-10', 3, 'Neither of us apologized, and the silence dragged on for months', 'لم يعتذر أي منا، واستمر الصمت لأشهر.', null, '[{"en":"Neither","ar":"لا"},{"en":"of","ar":"من"},{"en":"us","ar":"منا"},{"en":"apologized,","ar":"اعتذر،"},{"en":"and","ar":"و"},{"en":"the","ar":"الـ"},{"en":"silence","ar":"الصمت"},{"en":"dragged","ar":"استمر"},{"en":"on","ar":"مستمراً"},{"en":"for","ar":"لمدة"},{"en":"months","ar":"أشهر"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
