insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-10-s6', 'normal-10', 5, 'Deep down, though, I really missed having her around', 'لكن في أعماقي، اشتقت فعلاً لوجودها بجانبي.', null, '[{"en":"Deep","ar":"في"},{"en":"down,","ar":"الأعماق،"},{"en":"though,","ar":"لكن،"},{"en":"I","ar":"أنا"},{"en":"really","ar":"فعلاً"},{"en":"missed","ar":"اشتقت"},{"en":"having","ar":"لوجود"},{"en":"her","ar":"ها"},{"en":"around","ar":"بجانبي"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-10-s7', 'normal-10', 6, 'I finally sent a short message, just to check in', 'أرسلت أخيراً رسالة قصيرة، لمجرد الاطمئنان عليها.', null, '[{"en":"I","ar":"أنا"},{"en":"finally","ar":"أخيراً"},{"en":"sent","ar":"أرسلت"},{"en":"a","ar":"واحدة"},{"en":"short","ar":"قصيرة"},{"en":"message,","ar":"رسالة،"},{"en":"just","ar":"لمجرد"},{"en":"to","ar":"أن"},{"en":"check","ar":"أطمئن"},{"en":"in","ar":"عليها"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-10-s8', 'normal-10', 7, 'She replied almost instantly, as if she''d been waiting too', 'ردت على الفور تقريباً، وكأنها كانت تنتظر أيضاً.', null, '[{"en":"She","ar":"هي"},{"en":"replied","ar":"ردت"},{"en":"almost","ar":"تقريباً"},{"en":"instantly,","ar":"فوراً،"},{"en":"as","ar":"كأنها"},{"en":"if","ar":"لو"},{"en":"she''d","ar":"كانت"},{"en":"been","ar":"قد"},{"en":"waiting","ar":"تنتظر"},{"en":"too","ar":"أيضاً"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-10-s9', 'normal-10', 8, 'We''re rebuilding things slowly, and honestly, that feels like enough', 'نعيد بناء العلاقة تدريجياً، وبصراحة، هذا يبدو كافياً.', null, '[{"en":"We''re","ar":"نحن"},{"en":"rebuilding","ar":"نعيد بناء"},{"en":"things","ar":"الأمور"},{"en":"slowly,","ar":"تدريجياً،"},{"en":"and","ar":"و"},{"en":"honestly,","ar":"بصراحة،"},{"en":"that","ar":"هذا"},{"en":"feels","ar":"يبدو"},{"en":"like","ar":"وكأنه"},{"en":"enough","ar":"كافياً"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
