insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-11-s9', 'normal-11', 8, 'Whether it succeeds or not, I don''t regret taking the leap', 'سواء نجح أم لا، لا أندم على خوض هذه المخاطرة.', null, '[{"en":"Whether","ar":"سواء"},{"en":"it","ar":"هو"},{"en":"succeeds","ar":"نجح"},{"en":"or","ar":"أم"},{"en":"not,","ar":"لا،"},{"en":"I","ar":"أنا"},{"en":"don''t","ar":"لا"},{"en":"regret","ar":"أندم"},{"en":"taking","ar":"خوض"},{"en":"the","ar":"الـ"},{"en":"leap","ar":"المخاطرة"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-12-s1', 'normal-12', 0, 'The job offer came with a catch: it was only for one year', 'جاء عرض العمل مع شرط: أنه لمدة عام واحد فقط.', null, '[{"en":"The","ar":"الـ"},{"en":"job","ar":"الوظيفة"},{"en":"offer","ar":"عرض"},{"en":"came","ar":"جاء"},{"en":"with","ar":"مع"},{"en":"a","ar":"واحد"},{"en":"catch:","ar":"شرط:"},{"en":"it","ar":"أنه"},{"en":"was","ar":"كان"},{"en":"only","ar":"فقط"},{"en":"for","ar":"لمدة"},{"en":"one","ar":"عام"},{"en":"year","ar":"واحد"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-12-s2', 'normal-12', 1, 'Everyone around me assumed I''d turn it down immediately', 'افترض الجميع من حولي أنني سأرفضه فوراً.', null, '[{"en":"Everyone","ar":"الجميع"},{"en":"around","ar":"حول"},{"en":"me","ar":"ي"},{"en":"assumed","ar":"افترض"},{"en":"I''d","ar":"أنني"},{"en":"turn","ar":"سأرفض"},{"en":"it","ar":"ه"},{"en":"down","ar":"تماماً"},{"en":"immediately","ar":"فوراً"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-12-s3', 'normal-12', 2, 'Instead, I found myself seriously weighing the pros and cons', 'بدلاً من ذلك، وجدت نفسي أزن الإيجابيات والسلبيات بجدية.', null, '[{"en":"Instead,","ar":"بدلاً من ذلك،"},{"en":"I","ar":"أنا"},{"en":"found","ar":"وجدت"},{"en":"myself","ar":"نفسي"},{"en":"seriously","ar":"بجدية"},{"en":"weighing","ar":"أزن"},{"en":"the","ar":"الـ"},{"en":"pros","ar":"الإيجابيات"},{"en":"and","ar":"و"},{"en":"cons","ar":"السلبيات"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-12-s4', 'normal-12', 3, 'Leaving my apartment, my routine, and my friends felt daunting', 'بدا ترك شقتي وروتيني وأصدقائي أمراً مرهقاً.', null, '[{"en":"Leaving","ar":"ترك"},{"en":"my","ar":"لي"},{"en":"apartment,","ar":"شقتي،"},{"en":"my","ar":"لي"},{"en":"routine,","ar":"روتيني،"},{"en":"and","ar":"و"},{"en":"my","ar":"لي"},{"en":"friends","ar":"أصدقائي"},{"en":"felt","ar":"بدا"},{"en":"daunting","ar":"مرهقاً"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-12-s5', 'normal-12', 4, 'At the same time, staying felt like choosing comfort over growth', 'في الوقت نفسه، بدا البقاء وكأنه اختيار الراحة على النمو.', null, '[{"en":"At","ar":"في"},{"en":"the","ar":"الـ"},{"en":"same","ar":"نفس"},{"en":"time,","ar":"الوقت،"},{"en":"staying","ar":"البقاء"},{"en":"felt","ar":"بدا"},{"en":"like","ar":"وكأنه"},{"en":"choosing","ar":"اختيار"},{"en":"comfort","ar":"الراحة"},{"en":"over","ar":"على"},{"en":"growth","ar":"النمو"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-12-s6', 'normal-12', 5, 'I gave myself one week to decide, no more', 'منحت نفسي أسبوعاً واحداً لأقرر، لا أكثر.', null, '[{"en":"I","ar":"أنا"},{"en":"gave","ar":"منحت"},{"en":"myself","ar":"نفسي"},{"en":"one","ar":"واحداً"},{"en":"week","ar":"أسبوعاً"},{"en":"to","ar":"لـ"},{"en":"decide,","ar":"أقرر،"},{"en":"no","ar":"لا"},{"en":"more","ar":"أكثر"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-12-s7', 'normal-12', 6, 'In the end, uncertainty scared me less than regret did', 'في النهاية، أخافني الغموض أقل مما أخافني الندم.', null, '[{"en":"In","ar":"في"},{"en":"the","ar":"الـ"},{"en":"end,","ar":"النهاية،"},{"en":"uncertainty","ar":"الغموض"},{"en":"scared","ar":"أخافني"},{"en":"me","ar":"ني"},{"en":"less","ar":"أقل"},{"en":"than","ar":"مما"},{"en":"regret","ar":"الندم"},{"en":"did","ar":"فعل"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-12-s8', 'normal-12', 7, 'I signed the contract two days before the deadline', 'وقّعت العقد قبل يومين من الموعد النهائي.', null, '[{"en":"I","ar":"أنا"},{"en":"signed","ar":"وقّعت"},{"en":"the","ar":"الـ"},{"en":"contract","ar":"العقد"},{"en":"two","ar":"يومين"},{"en":"days","ar":"أيام"},{"en":"before","ar":"قبل"},{"en":"the","ar":"الـ"},{"en":"deadline","ar":"النهائي"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
insert into sentences (id, lesson_id, order_index, en, ar, speaker, word_translations, updated_at) values ('normal-12-s9', 'normal-12', 8, 'Whatever happens after that year, I know I made the braver choice', 'مهما حدث بعد ذلك العام، أعلم أنني اتخذت الخيار الأكثر جرأة.', null, '[{"en":"Whatever","ar":"مهما"},{"en":"happens","ar":"حدث"},{"en":"after","ar":"بعد"},{"en":"that","ar":"ذلك"},{"en":"year,","ar":"العام،"},{"en":"I","ar":"أنا"},{"en":"know","ar":"أعلم"},{"en":"I","ar":"أنني"},{"en":"made","ar":"اتخذت"},{"en":"the","ar":"الـ"},{"en":"braver","ar":"الأكثر جرأة"},{"en":"choice","ar":"الخيار"}]'::jsonb, now()) on conflict (id) do update set order_index = excluded.order_index, en = excluded.en, ar = excluded.ar, speaker = excluded.speaker, word_translations = excluded.word_translations, updated_at = now();
